from taf.hw.vertex.available_devices import AvailableVertexChannelEmulatorDevices
from taf.hw.vertex.exception import MultiDevicesFound


class VertexChannelEmulatorFactory(object):
    """
    A factory class to generate instance according by different configuration info
    """

    @classmethod
    def create(cls, model, version, **kwargs):
        available_vertex_instance = AvailableVertexChannelEmulatorDevices()
        device_class_list = available_vertex_instance.find_devices(model=model, version=version)
        device_class = None
        devices_number = len(device_class_list)
        if devices_number > 1:
            raise MultiDevicesFound('Found {} devices: {}'.format(devices_number, device_class_list))
        if devices_number == 1:
            device_class = device_class_list[0]
        if devices_number == 0:
            device_class = available_vertex_instance.find_default_device(model=model)
        return device_class(**kwargs)
